import {skillTitles,friendNotes,readLearning,recordLearning,medals} from './academy-learning.js';
import {questions,subjects,shuffledOptions} from './questions.js';
import {drawWorld} from './world.js';
import {loadAllArt,loadArt,heroes,companions} from './art.js';
import {maps,difficultyLabels,freshProgress,validProgress,newBattle,settle,npcTurn,damageByDifficulty,award,makeDeck} from './academy-core.js';
const $=id=>document.getElementById(id),KEY='anhoa-academy-v3',panel=$('panel'),quiz=$('quiz'),video=$('intro-video');
let progress=freshProgress(),saveFailed=false;
try{const raw=localStorage.getItem(KEY);if(raw)progress=validProgress(JSON.parse(raw));}catch{saveFailed=true;}
let mapIndex=progress.unlocked,battle=null,phase='ready',effect=null,visualWave=null,shieldAt=-1,deck=[],deckKey='',q=null,options=[],remaining=0,lastTick=0,interval=null,training=false,pausedPhase='question',audio=null,autoResumeVideo=false,routeSignature='',panelClose=null;
let learning=readLearning(progress.learning),streak=0,reviewing=false,reviewQueue=[];
const state={cls:progress.hero,element:1,pet:1,zone:0,wins:[0,0,0],background:maps[mapIndex].background};
const heroNames=['Pháp sư nhỏ','Vệ sĩ dũng cảm','Bạn của linh thú'];
function save(){progress.learning=learning;try{localStorage.setItem(KEY,JSON.stringify(progress));saveFailed=false;}catch{saveFailed=true;}renderSave();}
function renderSave(){$('save-status').textContent=saveFailed?'Chưa lưu được trên máy':'Đã lưu trên máy';$('save-status').classList.toggle('save-warning',saveFailed);}
function tone(kind){if(!progress.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='win'?[523,659,784,1046]:kind==='correct'?[659,880]:[330,262];notes.forEach((f,i)=>{const t=audio.currentTime+i*.13,o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.06,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.35);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.36);});}catch{/* Sound is optional. */}}
function setMessage(s){$('message').textContent=s;}
function render(){document.body.classList.toggle('battle-mode',!!battle||training);const map=maps[mapIndex];state.cls=progress.hero;state.element=map.element;state.pet=map.pet;state.background=map.background;
 $('chapter-number').textContent=`CHƯƠNG ${String(mapIndex+1).padStart(2,'0')} / 05`;$('map-name').textContent=map.name;$('map-place').textContent=map.place;
 $('fragments').textContent=progress.stars.filter(Boolean).length+' / 5 mảnh ghép';$('level-chip').textContent='Lớp 2 · '+difficultyLabels[progress.difficulty];
 $('wave-label').textContent=battle?`Lượt ${battle.turn+1} · ${phase==='npc'?'Đối thủ phản công':'Lượt của em'}`:'Chuẩn bị lên đường';
 $('enemy-name').textContent=battle?.wave?map.friend:'Linh thể lạc đường';$('fog-fill').style.width=(battle?battle.hp/battle.maxHp*100:100)+'%';$('fog-label').textContent=battle?`${battle.hp} / ${battle.maxHp} HP`:'Sương mù';
 const shield=battle?.shield??12;$('shield').textContent='♥ '+shield+' / 12';$('shield').setAttribute('aria-label',shield+' sinh lực');
 $('pet-image').src=`assets/${companions[map.pet]}.webp`;$('pet-image').alt=['Thiết Vũ','Mộc Miên','Giọt Mưa','Đốm Lửa','Đá Nhỏ'][map.pet];
 $('hero-image').src=`assets/${heroes[progress.hero]}.webp`;$('hero-image').alt=heroNames[progress.hero];$('hero-name').textContent=heroNames[progress.hero];$('total-correct').textContent=progress.correct;$('total-stars').textContent=progress.stars.reduce((a,b)=>a+b,0);
 $('combo-chip').hidden=streak<2||!battle;$('combo-chip').textContent='✦ '+streak+' câu đúng liên tiếp';$('turn-label').textContent=phase==='npc'?'ĐỐI THỦ ĐANG PHẢN CÔNG':reviewing?'GÓC ÔN TẬP':battle?skillTitles[progress.hero]:'MỘT CÂU ĐÚNG · MỘT PHÉP MÀU';$('attack').disabled=phase!=='ready';$('attack').textContent=battle?'Trả lời & ra chiêu →':'Bắt đầu khám phá →';
 for(const id of ['settings-open','journey-open','guide-open','parent-open','journal-open'])$(id).disabled=phase!=='ready';
 $('sound').setAttribute('aria-label',progress.sound?'Tắt âm thanh':'Bật âm thanh');$('sound').setAttribute('aria-pressed',String(progress.sound));$('sound').style.opacity=progress.sound?'1':'.6';
 const sig=[progress.unlocked,mapIndex,progress.stars.join(),phase==='ready'].join('|');if(sig!==routeSignature){routeSignature=sig;$('route-strip').replaceChildren();maps.forEach((m,i)=>{const b=document.createElement('button');b.className='route-node'+(i===mapIndex?' active':'');b.disabled=i>progress.unlocked||phase!=='ready';b.setAttribute('aria-label',`${i+1}. ${m.name}${i>progress.unlocked?' · Chưa mở':''}`);b.innerHTML=`<img src="assets/${m.background}.webp" alt=""><span><b>${i+1}. ${m.name}</b><small>${i>progress.unlocked?'Chưa mở':progress.stars[i]?'★'.repeat(progress.stars[i]):'Khám phá'}</small></span>`;b.onclick=()=>chooseMap(i);$('route-strip').append(b);});}renderSave();}
function openPanel(html,onClose=null){panelClose=onClose;$('panel-content').innerHTML=html;if(!panel.open)panel.showModal();}
function closePanel(){panel.close();const fn=panelClose;panelClose=null;if(fn)fn();else if(phase==='ready')$('attack').focus();}
$('panel-close').onclick=closePanel;panel.addEventListener('cancel',e=>{e.preventDefault();closePanel();});
function chooseMap(i){if(phase!=='ready'||i>progress.unlocked)return;const go=()=>{mapIndex=i;battle=null;effect=null;setMessage(maps[i].intro);render();};if(battle){openPanel('<p class="eyebrow">ĐỔI CHẶNG ĐƯỜNG</p><h2 id="panel-title">Về bản đồ khác?</h2><p>Trận đang chơi sẽ bắt đầu lại. Các mảnh ghép đã nhận vẫn được giữ.</p><div class="panel-actions"><button id="confirm-map" class="primary full">Đổi bản đồ</button><button id="cancel-map" class="quiet">Ở lại đây</button></div>');$('confirm-map').onclick=()=>{panel.close();go();};$('cancel-map').onclick=closePanel;}else go();}
function startBattle(){if(phase!=='ready')return;if(!progress.tutorialDone){tutorial(0);return;}reviewing=false;streak=0;battle=newBattle(mapIndex);setMessage(maps[mapIndex].intro);render();chooseDifficulty();}
function updateTimer(){if(!q)return;const total=progress.pace*1000;$('timer').textContent=total?Math.max(0,Math.ceil(remaining/1000))+' giây':'Không vội nhé';$('timer-fill').style.width=total?Math.max(0,remaining/total*100)+'%':'100%';}
function startClock(){clearInterval(interval);lastTick=performance.now();if(progress.pace&&!training&&!reviewing)interval=setInterval(()=>{const now=performance.now();if(!document.hidden&&phase==='question')remaining-=now-lastTick;lastTick=now;updateTimer();if(remaining<=0&&phase==='question')answer(-1);},100);}
function ask(trial=false){if(!trial&&phase!=='ready')return;training=trial;
 if(trial)q={id:'tutorial',subject:'math',topic:'Cùng thử một lần',prompt:'Mộc Miên có 2 chiếc lá, em tặng thêm 1 chiếc. Bạn ấy có tất cả mấy chiếc lá?',options:['3 chiếc lá','1 chiếc lá','2 chiếc lá','4 chiếc lá'],answer:0,explanation:'2 chiếc lá thêm 1 chiếc lá là 3 chiếc lá.'};
 else if(reviewing){const reviewId=reviewQueue.shift();q=questions.find(item=>item.id===reviewId);if(!q){reviewing=false;phase='ready';render();journal();return;}}
 else{const key=progress.subject+progress.difficulty;if(!deck.length||deckKey!==key){deck=makeDeck(questions,progress.subject,progress.difficulty);deckKey=key;}q=deck.pop();}
 $('difficulty-choice').hidden=true;$('question-content').hidden=false;options=shuffledOptions(q);phase='question';remaining=progress.pace*1000;
 $('qsubject').textContent=reviewing?'ÔN TẬP · '+subjects[q.subject]:training?'CÙNG MỘC MIÊN LUYỆN TẬP':'Lớp 2 · '+subjects[q.subject];$('qtopic').textContent=training?'BẤM VÀO ĐÁP ÁN EM CHỌN':difficultyLabels[q.difficulty||progress.difficulty]+' · '+q.topic;
 $('question').textContent=q.prompt;quiz.classList.toggle('long',q.prompt.length>130);$('feedback').textContent='';$('continue').hidden=true;$('leave-question').hidden=training;$('answers').replaceChildren();options.forEach((o,i)=>{const b=document.createElement('button'),badge=document.createElement('em'),label=document.createElement('span');badge.textContent='ABCD'[i];label.textContent=o.text;b.append(badge,label);b.onclick=()=>answer(i);$('answers').append(b);});updateTimer();if(reviewing){$('timer').textContent='Ôn tập · không giới hạn';$('timer-fill').style.width='100%';}if(training){$('timer').textContent='Lượt tập · không mất sinh lực';$('timer-fill').style.width='100%';}render();quiz.show();quiz.scrollTop=0;$('answers').firstElementChild.focus({preventScroll:true});startClock();}
function answer(index){if(phase!=='question')return;phase='feedback';clearInterval(interval);const correct=options[index]?.correct===true;
 [...$('answers').children].forEach((b,i)=>{b.disabled=true;if(options[i].correct)b.classList.add('correct');else if(i===index)b.classList.add('wrong');});
 $('feedback').textContent=(correct?'Đúng rồi! ':index<0?'Hết giờ rồi. Mình cùng xem nhé. ':'Mình cùng xem lại nhé. ')+q.explanation;
 $('continue').textContent=reviewing?'Câu tiếp theo →':correct?'Tung phép →':training?'Thử lại cùng Mộc Miên':'Mình đã hiểu →';$('continue').hidden=false;$('leave-question').hidden=true;$('continue').focus();tone(correct?'correct':'wrong');$('continue').onclick=()=>resolve(correct);}
function resolve(correct){if(phase!=='feedback')return;phase='animation';quiz.close();clearInterval(interval);
 if(reviewing){learning=recordLearning(learning,q.id,correct,0);save();phase='ready';if(reviewQueue.length){ask();}else{reviewing=false;render();journal();}return;}
 if(training){if(!correct){phase='ready';ask(true);return;}effect={time:performance.now(),damage:1,skill:true};setMessage('Tuyệt lắm! Em đã biết cách gửi một phép màu.');render();setTimeout(()=>{progress.tutorialDone=true;save();training=false;phase='ready';openPanel('<div class="panel-center"><img class="tutorial-pet" src="assets/pet-wood.webp" alt="Mộc Miên"><p class="eyebrow">EM ĐÃ SẴN SÀNG</p><h2 id="panel-title">Cùng lên đường nào!</h2><p>Trả lời đúng để xua sương. Nếu chưa đúng, đọc lời giải rồi thử câu tiếp theo nhé.</p><button id="finish-guide" class="primary full">Khám phá Hẻm An Hòa →</button></div>',()=>{render();});$('finish-guide').onclick=()=>{panel.close();panelClose=null;render();startBattle();};render();},850);return;}
 const oldWave=battle.wave;visualWave=oldWave;battle=settle(battle,correct,progress.difficulty);progress.attempts++;if(correct)progress.correct++;streak=correct?streak+1:0;learning=recordLearning(learning,q.id,correct,streak);save();
 if(correct){effect={time:performance.now(),damage:damageByDifficulty[progress.difficulty],skill:true,label:skillTitles[progress.hero],streak};setMessage(['Một lớp sương đã tan!','Linh thú đã nghe thấy em rồi.','Phép màu đang sáng hơn!'][battle.correct%3]);$('scene-feedback').textContent='−'+damageByDifficulty[progress.difficulty]+' HP';}
 else{setMessage('Phép chưa thành công. Chuẩn bị đón đòn của đối thủ.');$('scene-feedback').textContent='Phép thuật chưa thành công';}
 render(); // Keep the struck creature visible while its hit effect plays.
 setTimeout(()=>{visualWave=null;$('scene-feedback').textContent='';if(battle.status==='won'){progress=award(progress,battle);save();phase='result';showResult(true);}else if(battle.status==='lost'){phase='result';showResult(false);}else if(oldWave!==battle.wave){battle.status='active';phase='ready';openPanel(`<p class="eyebrow">CHẶNG CUỐI CỦA BẢN ĐỒ</p><h2 id="panel-title">${maps[mapIndex].friend} đang đợi</h2><p>Em đã dọn xong đường. Người giữ mảnh ghép có 400 HP.</p><button id="next-wave" class="primary full">Tiến lên →</button>`,()=>render());$('next-wave').onclick=()=>{panel.close();panelClose=null;render();chooseDifficulty();};}else{runNpcTurn();return;}render();},correct?850:700);}
function showResult(won){if(won)effect={time:performance.now(),kind:'victory',duration:2000};const map=maps[mapIndex],all=progress.stars.every(Boolean);tone(won?'win':'wrong');openPanel(`<div class="panel-center"><p class="eyebrow">${won?'MẢNH GHÉP ĐÃ TRỞ VỀ':'NGHỈ MỘT CHÚT NHÉ'}</p><h2 id="panel-title">${won?(all?'An Hòa đã thức giấc!':map.relic):'Mình cùng thử lại'}</h2>${won?`<img class="reward-pet" src="assets/${map.enemies[1]}.webp" alt="Linh thú đồng hành"><p class="notice">Đã lưu mảnh ghép vào Sổ tay linh thú</p>`:''}<div class="result-stars">${won?'★'.repeat(Math.max(1,3-battle.mistakes)):'◇ ◇ ◇'}</div><p>${won?map.outro:'Có những câu cần thêm một lần làm quen. Những điều em đã học vẫn ở lại cùng em.'}</p><p class="notice">${battle.correct} câu đúng · ${battle.mistakes} lần cần ôn lại</p><div class="panel-actions"><button id="result-next" class="primary full">${won?(all?'Xem hành trình':'Đến bản đồ tiếp theo →'):'Thử lại bản đồ'}</button><button id="result-back" class="quiet">Về hành trình</button></div></div>`,()=>{phase='ready';battle=null;render();});$('result-next').onclick=()=>{panel.close();panelClose=null;phase='ready';battle=null;if(won&&all){render();journey();}else if(won){mapIndex=Math.min(4,mapIndex+1);render();setMessage(maps[mapIndex].intro);startBattle();}else{render();startBattle();}};$('result-back').onclick=()=>{panel.close();panelClose=null;phase='ready';battle=null;render();journey();};}
function pause(){if(!['question','feedback'].includes(phase)||training)return;pausedPhase=phase;phase='paused';clearInterval(interval);quiz.close();openPanel('<p class="eyebrow">TẠM DỪNG</p><h2 id="panel-title">Mộc Miên sẽ đợi em.</h2><p>Câu hỏi và thời gian còn lại được giữ nguyên.</p><div class="panel-actions"><button id="resume" class="primary full">Tiếp tục câu hỏi</button><button id="retreat" class="quiet">Kết thúc trận này</button></div>',resume);$('resume').onclick=resume;$('retreat').onclick=()=>{panel.close();panelClose=null;phase='ready';battle=null;reviewing=false;render();setMessage('Khi sẵn sàng, mình lại lên đường nhé.');};}
function resume(){panel.close();panelClose=null;phase=pausedPhase;quiz.show();if(phase==='question')startClock();}
quiz.addEventListener('cancel',e=>{e.preventDefault();if(phase==='choose'){quiz.close();phase='ready';render();}else pause();});$('leave-question').onclick=pause;
function tutorial(step){const content=[['Chào em, mình là Mộc Miên!','An Hòa đang chìm trong sương. Mỗi câu trả lời đúng sẽ giúp mình gửi một phép màu.'],['Chọn một trong bốn đáp án','Đọc câu hỏi, rồi bấm câu em chọn. Nếu chưa đúng, mình sẽ cùng em xem lời giải.'],['Em và đối thủ thay phiên nhau','Chọn Dễ, Bình thường hoặc Khó trước mỗi lượt: gây 100, 125 hoặc 150 sát thương. Sau đó đối thủ phản công: mất 1 sinh lực nếu em trả lời đúng, 2 nếu chưa đúng.']];phase='tutorial';render();openPanel(`<div class="panel-center"><img class="tutorial-pet" src="assets/pet-wood.webp" alt="Mộc Miên"><div class="step-dots">${content.map((_,i)=>`<i class="${i===step?'on':''}"></i>`).join('')}</div><h2 id="panel-title">${content[step][0]}</h2><p>${content[step][1]}</p><button id="guide-next" class="primary full">${step===2?'Thử gửi một phép màu':'Tiếp theo →'}</button></div>`,()=>{phase='ready';progress.tutorialDone=true;save();render();});$('guide-next').onclick=()=>{panel.close();panelClose=null;if(step<2)tutorial(step+1);else{phase='ready';ask(true);}};}
function journey(){if(phase!=='ready')return;openPanel('<p class="eyebrow">NĂM MẢNH TRI THỨC</p><h2 id="panel-title">Hành trình của em</h2><div class="map-list" id="map-list"></div><p class="notice">Hoàn thành bản đồ để mở vùng đất kế tiếp. Em có thể chơi lại những nơi đã mở.</p>');maps.forEach((m,i)=>{const b=document.createElement('button');b.disabled=i>progress.unlocked;b.innerHTML=`<img src="assets/${m.background}.webp" alt=""><span><b>${i+1}. ${m.name}</b><small>${i>progress.unlocked?'Chưa mở':progress.stars[i]?'★'.repeat(progress.stars[i]):m.place}</small></span>`;b.onclick=()=>{panel.close();chooseMap(i);};$('map-list').append(b);});}
function settings(){if(phase!=='ready')return;openPanel(`<p class="eyebrow">CHƠI THEO NHỊP CỦA EM</p><h2 id="panel-title">Tùy chọn</h2><div class="settings-grid"><label>Môn học<select id="subject"><option value="all">Cả bốn môn</option>${Object.entries(subjects).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Mức câu hỏi<select id="difficulty">${Object.entries(difficultyLabels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>Nhân vật<select id="hero">${heroNames.map((t,i)=>`<option value="${i}">${t}</option>`).join('')}</select></label><label>Thời gian<select id="pace"><option value="0">Không giới hạn</option><option value="15">Thử thách 15 giây</option></select></label></div><p class="notice">Với câu đọc dài, em có thể chọn không giới hạn thời gian. Đổi tùy chọn không làm mất mảnh ghép.</p><div class="panel-actions"><button id="apply-settings" class="primary full">Lưu tùy chọn</button><button id="replay-story" class="quiet">Xem lại câu chuyện</button><button id="replay-guide" class="quiet">Xem hướng dẫn</button></div>`);for(const id of ['subject','difficulty','hero','pace'])$(id).value=String(progress[id]);$('apply-settings').onclick=()=>{progress.subject=$('subject').value;progress.difficulty=$('difficulty').value;progress.hero=Number($('hero').value);progress.pace=Number($('pace').value);deck=[];save();panel.close();render();};$('replay-story').onclick=()=>{panel.close();showIntro();};$('replay-guide').onclick=()=>{panel.close();tutorial(0);};}
function parents(){openPanel('<p class="eyebrow">DÀNH CHO PHỤ HUYNH</p><h2 id="panel-title">Học bằng những bước nhỏ</h2><p>300 câu: 100 Dễ, 100 Bình thường, 100 Khó. Toán 120 câu; ba môn còn lại mỗi môn 60 câu. Có các biến thể cùng dạng bài, không phải 300 mục tiêu học tập khác nhau.</p><p class="notice">Câu hỏi tự biên soạn và tự kiểm tra; chưa được giáo viên thẩm định, chưa đối chiếu đầy đủ mọi trang PDF hoặc xác nhận ấn bản 2026. Tiếng Anh là nội dung làm quen tự chọn. Độ khó là mức đề xuất, không dùng kết quả chơi để kết luận năng lực của trẻ.</p><p><a href="question-bank.json" download>Tải JSON</a> · <a href="question-bank.csv" download>Tải bảng CSV</a> · <a href="sources.html">Nguồn và phạm vi</a></p><p class="notice">Tiến độ bản đồ lưu trên trình duyệt này. Trận đang chơi bắt đầu lại khi tải lại trang. Không yêu cầu tên, email hoặc tài khoản. Bản mở đầu là phim minh họa 10 giây; hình nền được tạo với AI, hiệu ứng và giao diện được lập trình cho game.</p>');}
function showIntro(){document.body.classList.remove('at-title');$('title-screen').hidden=true;phase='intro';render();video.currentTime=0;video.muted=!progress.sound;$('play-intro').disabled=false;$('play-intro').textContent='Xem câu chuyện · 10 giây';$('story').showModal();}
function finishIntro(){video.pause();$('story').close();progress.introSeen=true;save();phase='ready';if(!progress.tutorialDone)tutorial(0);else render();}
$('play-intro').onclick=async()=>{video.muted=!progress.sound;try{await video.play();$('play-intro').disabled=true;$('play-intro').textContent='Đang kể chuyện…';}catch{$('play-intro').textContent='Chạm để phát lại';}};
video.addEventListener('timeupdate',()=>{const t=video.currentTime;$('film-time').textContent=`00:${String(Math.min(10,Math.floor(t))).padStart(2,'0')} / 00:10`;$('story-title').textContent=t<3.4?'Khi thành phố quên mất tên mình…':t<6.7?'Một người bạn nhỏ đã tìm đến.':'Năm mảnh tri thức. Một bình minh.';$('story-caption').textContent=t<3.4?'Một màn sương lạ làm những linh thú lạc đường.':t<6.7?'“Em có muốn cùng mình giúp An Hòa không?”':'Mỗi câu trả lời đúng sẽ thắp sáng một phần thành phố.';});video.onended=finishIntro;video.onerror=()=>{$('play-intro').textContent='Video chưa tải được · thử lại';};$('skip-intro').onclick=finishIntro;$('story').addEventListener('cancel',e=>{e.preventDefault();finishIntro();});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden&&phase==='intro'&&!video.paused){autoResumeVideo=true;video.pause();}else if(!document.hidden&&autoResumeVideo&&phase==='intro'){autoResumeVideo=false;video.play().catch(()=>{$('play-intro').disabled=false;});}});
$('attack').onclick=()=>battle?chooseDifficulty():startBattle();$('journey-open').onclick=journey;$('settings-open').onclick=settings;$('guide-open').onclick=()=>tutorial(0);$('parent-open').onclick=parents;$('sound').onclick=()=>{progress.sound=!progress.sound;save();render();tone('correct');};
let lastFrame=0;function frame(t){if(!document.hidden&&t-lastFrame>32){const m=maps[mapIndex],f={artId:m.enemies[visualWave??battle?.wave??0],large:!!(visualWave??battle?.wave)};drawWorld($('world'),state,f,effect,t);if(shieldAt>=0&&t-shieldAt<700){const c=$('world').getContext('2d'),p=(t-shieldAt)/700;c.save();c.globalAlpha=Math.sin(p*Math.PI)*.65;c.strokeStyle='#b5e6d1';c.lineWidth=5;c.beginPath();c.ellipse(340,335,65,110,0,0,Math.PI*2);c.stroke();c.restore();}lastFrame=t;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
render();setMessage(maps[mapIndex].intro);Promise.all([loadAllArt(),loadArt('bg-library'),loadArt('bg-rooftop')]).then(([r,a,b])=>{if(!a||!b||r.some(x=>!x.ok))setMessage('Một số hình chưa tải xong. Nếu cảnh trống, em hãy tải lại trang nhé.');});phase='title';render();$('resume-journey').hidden=!progress.introSeen;

function chooseDifficulty(){if(phase!=='ready')return;phase='choose';training=false;$('difficulty-choice').hidden=false;$('question-content').hidden=true;quiz.show();render();}
for(const button of document.querySelectorAll('[data-level]'))button.onclick=()=>{if(phase!=='choose')return;progress.difficulty=button.dataset.level;save();quiz.close();phase='ready';ask();};
function runNpcTurn(){phase='npc';effect={time:performance.now(),kind:'npc',duration:1000,damage:battle.guard?1:2,guard:battle.guard,label:['Bụi sao xoáy','Cánh giấy lạc','Lá cuốn','Sóng ký ức','Tia lửa nhỏ'][mapIndex]};$('turn-label').textContent='LƯỢT ĐỐI THỦ';setMessage('Đối thủ đang gom linh khí để phản công…');render();setTimeout(()=>{const loss=battle.guard?1:2;battle=npcTurn(battle);shieldAt=performance.now();$('scene-feedback').textContent='−'+loss+' sinh lực';render();setTimeout(()=>{$('scene-feedback').textContent='';if(battle.status==='lost'){phase='result';showResult(false);}else{phase='ready';$('turn-label').textContent='LƯỢT CỦA EM';setMessage('Đến lượt em. Chọn độ khó để chuẩn bị phép thuật.');}render();},450);},550);}
$('begin-story').onclick=()=>{showIntro();$('play-intro').onclick();};
$('resume-journey').onclick=()=>{document.body.classList.remove('at-title');$('title-screen').hidden=true;phase='ready';if(!progress.tutorialDone)tutorial(0);else render();};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen();return;}await document.documentElement.requestFullscreen();try{await screen.orientation?.lock?.('landscape');}catch{setMessage('Thiết bị này tự đổi bố cục theo chiều em cầm máy.');}}catch{setMessage('Em có thể xoay điện thoại; giao diện sẽ tự thích ứng.');}};

// Native Android Back closes the current task before offering to leave the app.
window.academyBack=()=>{if($('story').open){finishIntro();return true;}if(panel.open){closePanel();return true;}if(phase==='choose'){quiz.close();phase='ready';render();return true;}if(quiz.open&&!training){pause();return true;}if(['animation','npc','tutorial'].includes(phase)||training)return true;return false;};

function journal(){if(phase!=='ready')return;const missed=learning.missed.filter(id=>questions.some(q=>q.id===id));openPanel(`<p class="eyebrow">MỖI BƯỚC NHỎ ĐỀU ĐƯỢC GHI NHỚ</p><h2 id="panel-title">Sổ tay linh thú</h2><div class="friend-album">${maps.map((m,i)=>`<article class="friend-sticker ${progress.stars[i]?'earned':''}"><img src="assets/${m.enemies[1]}.webp" alt=""><b>${m.friend}</b><small>${progress.stars[i]?friendNotes[i]:'Hoàn thành '+m.name+' để nhận mảnh ghép'}</small><span>${progress.stars[i]?'★'.repeat(progress.stars[i]):'Chưa khám phá'}</span></article>`).join('')}</div><h3>Huy hiệu của em</h3><div class="medal-list">${medals(progress,learning).map(m=>`<p class="${m.earned?'earned':''}"><b>${m.earned?'✦':'◇'} ${m.name}</b><small>${m.detail}</small></p>`).join('')}</div><h3>Cùng hiểu thêm một chút</h3><p>${missed.length?'Có '+missed.length+' câu để cùng ôn lại. Không mất sinh lực và không giới hạn thời gian.':'Chưa có câu cần ôn lại. Mỗi lần chưa đúng, câu hỏi sẽ được lưu ở đây.'}</p>${missed.length?'<button id="review-start" class="primary full">Ôn tối đa 5 câu →</button>':''}<p class="notice">Chuỗi tốt nhất: ${learning.best} câu. Ôn tập không cộng sao hoặc sát thương. Các phần thưởng được lưu trên thiết bị này.</p>`);if(missed.length)$('review-start').onclick=()=>{if(battle){$('panel-content').insertAdjacentHTML('beforeend','<p class="notice">Hãy kết thúc trận đang chơi trước khi vào góc ôn tập.</p>');$('review-start').disabled=true;return;}panel.close();panelClose=null;reviewQueue=missed.slice(0,5);reviewing=true;ask();};}
$('journal-open').onclick=journal;
